WITH with_latest AS (SELECT s.*, latest.store_sale_revenue, latest.sale_date FROM stores s LEFT JOIN LATERAL (SELECT c.revenue AS store_sale_revenue, c.sale_date FROM store_sales c WHERE c.store_id = s.id AND c.sale_date <= s.opened_date ORDER BY c.sale_date DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT id, store_name, city, region, opened_date, CASE WHEN city RLIKE '^(Chiang Mai|Berlin)$' THEN 'GROUP_A' WHEN city RLIKE '^(Bangkok|New York)$' THEN 'GROUP_B' ELSE 'PRIORITY' END AS city_zone FROM with_latest
